import type { CSSProperties, ReactNode, Ref } from "react";
import type {
	VerificationsHandle,
	VerificationsOptions,
	KycElementProps,
	KycElementCreateOptions,
	KycElementHandle,
	CapabilitiesElementProps,
	CapabilitiesElementCreateOptions,
	CapabilitiesElementHandle,
	RfiElementProps,
	RfiElementCreateOptions,
	RfiElementHandle,
	ActionRequiredItem,
} from "@whop/elements/verifications";
export type {
	VerificationsHandle,
	VerificationsOptions,
	KycElementProps,
	KycElementCreateOptions,
	KycElementHandle,
	CapabilitiesElementProps,
	CapabilitiesElementCreateOptions,
	CapabilitiesElementHandle,
	RfiElementProps,
	RfiElementCreateOptions,
	RfiElementHandle,
	ActionRequiredItem,
};
type ElementProps<Options, Handle> = Options & {
	/** The element's live handle (same surface as the vanilla `create` return). */
	ref?: Ref<Handle>;
	/** Applied to the element's mount container (the wrapper this component renders; the element itself lives in its own frame, see the Styling docs for restyling it). */
	className?: string;
	/** Applied to the element's mount container (the wrapper this component renders). */
	style?: CSSProperties;
	/** Shown until the element is fully loaded. When omitted, the element's own internal loading UI is shown instead. */
	fallback?: ReactNode;
};

/**
 * Collects and verifies identity information for an account. Mount `kyc` for a complete KYC or KYB flow backed by the Verifications API.
 * Provider component: creates the VerificationsHandle and drives the element components rendered as children. `fallback` shows until every child element has loaded (grouped); `ref` exposes the live handle. Unmounting it destroys the handle and everything it created.
 * @example
 * ```tsx
 * import { WhopElements, Verifications, KycElement, CapabilitiesElement, RfiElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Verifications>
 *         <KycElement />
 *         <CapabilitiesElement />
 *         <RfiElement />
 *       </Verifications>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/verifications/overview
 */
export declare function Verifications(
	props: VerificationsOptions & { children?: ReactNode; fallback?: ReactNode; ref?: Ref<{ handle: VerificationsHandle | null }> },
): ReactNode;
/**
 * The nearest `<Verifications>` ancestor's live handle, `null` until it boots. Must be called under a `<Verifications>`.
 * @see https://docs.whop.com/elements/latest/verifications/overview
 */
export declare function useVerifications(): VerificationsHandle | null;

/**
 * A complete identity-verification flow. It collects individual KYC or business KYB details, starts or resumes the hosted provider session, handles follow-up information and document requests, polls status, and renders the final result without requiring the host to build verification UI.
 * @example
 * ```tsx
 * import { WhopElements, Verifications, KycElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Verifications>
 *         <KycElement />
 *       </Verifications>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/verifications/kyc
 */
export declare function KycElement(props: ElementProps<KycElementCreateOptions, KycElementHandle>): ReactNode;
/**
 * The account's verification standing: whether individual and business verification are done, and which capabilities that unlocks. Read-only — pressing a verify button reports `verificationRequested` and stays put, so the host mounts its own flow, such as this namespace's `kyc` element. Both halves can be hidden, so a host that only wants the capability list, or only the two verification rows, can drop the other.
 * @example
 * ```tsx
 * import { WhopElements, Verifications, CapabilitiesElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Verifications>
 *         <CapabilitiesElement />
 *       </Verifications>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/verifications/capabilities
 */
export declare function CapabilitiesElement(props: ElementProps<CapabilitiesElementCreateOptions, CapabilitiesElementHandle>): ReactNode;
/**
 * Everything the account still owes compliance, and the forms to answer it. Each row is one group of requirements — grouped by the system that asked, because each relays to its provider once its own items are answered — and pressing it opens that group’s form in place. Rows already with a reviewer are shown but not answerable. Renders an all-clear once nothing is outstanding, so it can sit permanently in a settings page.
 * @example
 * ```tsx
 * import { WhopElements, Verifications, RfiElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Verifications>
 *         <RfiElement />
 *       </Verifications>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/verifications/rfi
 */
export declare function RfiElement(props: ElementProps<RfiElementCreateOptions, RfiElementHandle>): ReactNode;
